/* Jessica's animated laboratory, ported from round three's laboratory.css and problem-story.css. */

/* DM Sans, the face of her monitor's labels. */
@font-face {
  font-family: "Half Life Sans";
  src: url("./assets/dm-sans-latin-normal.woff2") format("woff2");
  font-style: normal;
  font-weight: 100 1000;
  font-display: swap;
}

.lab {
  position: absolute;
  inset: 0;
  --duration-step: 350ms;

  /* The homepage story (Jessica's Half Life illustrations): night-lab navy, ice-blue ink. */
  --story-night: #07172b;
  --story-deep: #061328;
import story1 from "./assets/story-1.webp";
import story2 from "./assets/story-2.webp";
import story3 from "./assets/story-3.webp";

/*
 * What the introduction borrows from Jessica's Half Life site (Jessica-mak/half-life-ui): her
 * lab's four chapters, and details cut from her three story illustrations.
 */

export interface LabChapter {
  };

  return (
    <section
      className={cx(styles.root, className)}
      aria-label="Half Life workflow"
      data-playing={playback.playing}
      data-reduced={playback.reduced}
    >
      <div className={styles.scroller}>
        <div
          className={styles.canvas}
          ref={canvas}
          role="group"
          aria-label="Half Life technical workflow"
        >
          <svg
            className={styles.routes}
      intro: "Each search is saved with the data it used, so you can come back to it.",
    },
  ],

  /** The introduction at `/`: the approach, its four steps, and the way into the app. */
  intro: {
    title: "Repurposing existing drugs for diseases",
    tagline: "A second life for existing medicines",
    solution:
      "Half Life integrates biological network analysis and AI evidence review to prioritise existing drugs for further research.",
    start: "Start exploring",
    limit: "Research hypotheses, not proven treatments.",
    method: [
      {
        title: "Disease proteins",
        text: "Proteins linked to the disease, from published genetic and clinical evidence.",
      },
      {
        title: "Network ranking",
        text: "Approved drugs ranked by how closely their targets connect to those proteins.",
      },
